        ["S_3e3c8068bb"] = "Ошибка",
        ["S_3e44b2a933"] = "Выбрать все",
        ["S_3ecf94020c"] = "<li class=\"warn\">Достигнут предел записей, сбор прерван: отчёт охватывает только данные до этого предела.</li>",
        ["S_3f140eb0af"] = "Интерфейс не открывается, чтение невозможно.",
        ["S_3f17e10afc"] = "Закрепить положение индикатора",
        ["S_3faff71558"] = "Ошибка: {0}\n\n",
        ["S_3fd7c734f2"] = "В отчёте это поле пустое, идентифицировать устройство по нему нельзя.",
        ["S_3ff8c35b3e"] = "Ожидание первого пакета — большинство устройств отправляют его в течение 1–5 с",
        ["S_4012c7053d"] = "Запишите несколько разных уровней заряда (например, при разряде и зарядке) и сравните их, чтобы сузить поиск до настоящего байта заряда.</p>",
        ["S_401f5099a6"] = "Сбросить положение индикатора",
        ["S_40ffb34860"] = "Проверить",
        ["S_41348bc6ad"] = "- Устройство: не выбрано (только данные уровня сеанса)",
        ["S_4241f9400c"] = "---- Стек вызовов ----\n",
        ["S_427e563587"] = "длительность {0}",
        ["S_4291e16ff4"] = "Остальные параметры сохранены, но запись автозапуска в реестр не удалась; в этот раз он не сработает.\n\n",
        ["S_4299e0fd82"] = "Не в сети · последний ответ {0:MM-dd HH:mm}",
        ["S_42d4c37781"] = "Сессия сбора уже запущена, сначала остановите её.",
        ["S_432b8537b8"] = "Отменить сбор",
        ["S_4370d05bfd"] = "Устройство не в сети, значение не получено",
        ["S_4383c7c62e"] = "Устройство BLE",
        ["S_44542b2183"] = "Инициализация служб и окон",
        ["S_4460e4103e"] = "- Группа {0} report={1} длина={2}: {3} записей,",
        ["S_448e2dcd51"] = "Все детали, включая дампы кадров и список интерфейсов; журнал получается большим. Изменение вступит в силу после перезапуска.",
        ["S_44a39befd7"] = "Устройство не предоставило",
        ["S_44f84d7a3f"] = "Выведено из ответа ресивера",
        ["S_45cad31a9f"] = "Отключите второе устройство той же модели или подключите к другому порту USB и повторите перечисление.",
        ["S_45eaa14106"] = "- Способ: USB/HID (выбрано пользователем, во время сбора не переключался)",
        ["S_46a179caea"] = "Сбор · записей {0} · ошибок {1}",
        ["S_46d44a2671"] = "Настроить изображение устройства",
        ["S_46f3cd7691"] = "выбран не тот интерфейс или тип канала этого интерфейса не является входным отчётом.</p></section>",
        ["S_47083917bb"] = "Если нужны исходные байты, захватите шину через USBPcap или используйте usbhid-dump в Linux.",
        ["S_479fcc1cc0"] = "Позже",
        ["S_47a40bc22e"] = "Выбрано: {0} · остальные не показываются",
        ["S_47a991d18c"] = "Тип устройства",
        ["S_47ff50df51"] = "Acrylic: Mica недоступна (нужна Windows 11), автоматически включён Acrylic",
        ["S_48367fdef0"] = "Шаг {0} · {1}",
        ["S_485b5d4308"] = "Не определённая возможность устройства",
        ["S_4917bcf0d6"] = "Всего завершено шагов: {0}",
