        ["S_4989b5cf94"] = "Управление",
        ["S_4a13900d1f"] = "Удалить устройство навсегда (добавить в чёрный список: больше не сканируется; для восстановления используйте «Заблокированные устройства» внизу страницы)",
        ["S_4a1f76212a"] = ", канал с большим буфером обычно не отправляет данные сам",
        ["S_4a32cfaba6"] = "Например: 13 4A 00 00 …",
        ["S_4a544fa16d"] = "Чтение Feature report (только чтение)",
        ["S_4aa48f0d6c"] = "Совпадений нет",
        ["S_4ab7348381"] = "Предположение",
        ["S_4afad87755"] = "Авто",
        ["S_4b2fed5e5a"] = "- +{0}мс пользователь видел {1}% → {2}",
        ["S_4b3fa0d869"] = "Сначала проверить",
        ["S_4bf06d36f9"] = "<li>Не собрано: исходные байты дескриптора HID-отчёта (в пользовательском режиме нет такого API), запись на уровне шины USB (нужен USBPcap),",
        ["S_4c70ede8c2"] = "- Локальный путь: {0}",
        ["S_4c790c1808"] = "Проверка обновлений не удалась:",
        ["S_4cd3698d30"] = "Неверный кадр может перевести устройство в bootloader или нарушить его работу. Продолжить?",
        ["S_4d0b4688c7"] = "Отмена",
        ["S_4d76d6cd3b"] = "<th>Записей на шаге</th><th>Изменившиеся байты</th><th>Новые группы на шаге</th></tr></thead><tbody>",
        ["S_4dd6926e26"] = "Контакты",
        ["S_4de50894b8"] = "Журнал",
        ["S_4dfddc9137"] = "Показывать уведомление в трее при заряде ниже этого значения; 0 — отключить",
        ["S_4e1ff3eb77"] = "Возможности",
        ["S_4e3f70279f"] = "Установка версии {0} отложена",
        ["S_4e6ff8e11b"] = "### Результаты сбора (факты)",
        ["S_4e7ca7eb5d"] = " записей, длина ",
        ["S_4e83f5d9e4"] = "Устройство не вернуло строковый дескриптор",
        ["S_4e8d6a51eb"] = "Если официальное ПО или плагин этого приложения опрашивает тот же интерфейс, сбор может быть нарушен, но доказать это нельзя.",
        ["S_4f9f259534"] = "<li>Исходные байты дескриптора HID-отчёта: в пользовательском режиме недоступны, в отчёте отсутствуют.</li>",
        ["S_4fb1035e42"] = "<th>Смещения со значением, равным заряду</th></tr></thead><tbody>",
        ["S_50f22cae43"] = "- Локальный путь: <укажите здесь путь к сохранённому vigilwatt-capture.zip>",
        ["S_5121afe913"] = "Всего записей",
        ["S_5157e89e22"] = "(оценка)",
        ["S_515e20b89b"] = "Было ли переключение способа",
        ["S_5171766471"] = "Загрузка версии {0}…",
        ["S_517833af13"] = "<p class=\"warn\">Этот интерфейс использует стандартную страницу назначения HID (usage page 0x",
        ["S_519b492857"] = "В SVG-пути отсутствует команда @{0}",
        ["S_520cb0e751"] = "Для этого устройства нет истории.",
        ["S_5232f5860c"] = "Окончание (местное время)",
        ["S_5270720394"] = "Неизвестный монитор",
        ["S_52f8f1cd34"] = "Устройству будет отправлено байт: {0}\n\n{1}\n\n",
        ["S_531252ed39"] = "<li>Полный обмен на уровне шины USB: в этот раз не собран.</li>",
        ["S_5363ff33e5"] = "Системно-защищённая collection всё равно откажет в доступе; эта функция не повышает права скрытно.",
        ["S_53685a7ef7"] = "USBPcapCMD.exe не найден",
        ["S_536a52843f"] = "<li>Собрано: данные перечисления устройств, caps интерфейсов HID, входные отчёты, реально прочитанные через HID API",
        ["S_544ce57eda"] = "Шаг 1 из 5",
        ["S_54981e1871"] = "Интерфейс не использует report ID, первый байт — данные",
        ["S_54b8b5f0b1"] = "{0}\n\nПосле удаления восстановить нельзя.",
        ["S_54d63cc0ba"] = "Совпадений нет",
        ["S_5521e368d8"] = "Предупреждение",
        ["S_55c1b91e9d"] = "Ошибок: {0} · длительность {1:0.0} с",
        ["S_55ffda672c"] = "Вернуться к списку устройств (Esc)",
        ["S_562088c9a7"] = "Только устройство с минимальным зарядом, самый узкий индикатор",
        ["S_56739dfb15"] = "- Время: с {0:yyyy-MM-dd HH:mm:ss},",
        ["S_56a8263d85"] = "Если нужна проверка записи, используйте существующий в проекте механизм плагинов или отдельный скрипт, а не страницу сбора.",
        ["S_571ac97bd8"] = "В SVG-пути отсутствует число @{0}",
        ["S_57308f49e2"] = "Во время сбора нет логики автоматического перехода на Bluetooth, фирменное ПО или другие интерфейсы.</p></section>",
        ["S_5845075331"] = "Необязательно. Укажите заряд, показанный в фирменном ПО или на устройстве: отчёт сравнит его с совпадающими байтами в пакетах (лишь косвенная подсказка). Оставьте пустым или укажите 0, чтобы не использовать.",
        ["S_5850267398"] = "{0}; … (всего {1})",
        ["S_586c0bdf09"] = "Есть входной канал (in {0}",
        ["S_58887d70b1"] = "Клавиатура, мышь и геймпад 2,4 ГГц",
        ["S_59cfa9a896"] = "Не удалось очистить журналы: ",
        ["S_5a07ebcbf3"] = "Каталог журнала: {0}\\logs\n\n",
        ["S_5a2b54e36a"] = "Требуется {0} байт, {1}.\n",
        ["S_5aa43f8953"] = "Загрузку обновления нужно запускать в потоке пользовательского интерфейса",
        ["S_5b612cbd3a"] = "Подготовка загрузки…",
        ["S_5b85f3f010"] = "Возможные причины: изменены права на каталог данных, заполнен диск или вмешательство антивируса.",
        ["S_5b95ff9028"] = "{0} · {1} дн",
        ["S_5bda8fde54"] = "Нельзя различить отдельные экземпляры одной модели.",
        ["S_5d1474054c"] = "Выбор интерфейса и проверка",
        ["S_5d2fdf1b0b"] = "Сессия не была завершена (приложение закрыли во время сбора), отчёт не создан; открыт каталог исходных записей.",
        ["S_5d55e288de"] = "Версия",
        ["S_5de955fd0f"] = "Эталонный уровень заряда ещё не записан.",
        ["S_5e2dfc2014"] = "Показывать батарею ноутбука в списке устройств, виджете и статистике. На настольном ПК без батареи не отображается",
        ["S_5e6bbc543f"] = "Windows не показывает заряд беспроводных устройств 2,4 ГГц, поэтому появился этот трей.",
        ["S_5e9b40fad7"] = "Введите имя устройства",
        ["S_5e9fff0e00"] = "У этого интерфейса нет выходного канала",
        ["S_5ebfb7fe1e"] = "Установлена последняя версия ({0})",
        ["S_5f05735f2d"] = "Внимание: это само по себе мышь/клавиатура. На шаге «выключить устройство» курсор исчезнет — завершите шаг сочетанием Ctrl+Enter.",
        ["S_5fec9621c1"] = "Mica: полупрозрачный материал в тон обоям (только Windows 11)",
        ["S_60162d6a9a"] = " · {0} зап.",
        ["S_607b2e73db"] = "- Значение байтов в группах пока не подтверждено; нужно повторить сбор, сравнивая с физическим состоянием устройства (кнопки, переключение режима, зарядка).",
        ["S_60841619b3"] = "<section><h2>Краткое резюме (можно скопировать)</h2><pre class=\"summary\">",
        ["S_60a4d475c3"] = "Сбор исходных данных: устройство → интерфейс → проверка → запись → отчёт",
        ["S_60f304aeca"] = "Нет данных измерений",
        ["S_613f7a44e2"] = "Подробно",
        ["S_626757d0c9"] = "</b> ",
        ["S_6291cde9c3"] = "При включении дескриптор сессии запросит доступ на запись, и появится «Отправка кадра». Используйте только если точно знаете, что отправляете: неверный кадр может перевести устройство в bootloader.",
        ["S_62a303b84a"] = "У интерфейса только Feature-канал: включите «Чтение Feature report» и выберите report ID, иначе данных не будет.",
        ["S_63c3524b0a"] = "При запуске проверяется GitHub Releases, при недоступности используется Gitee; перед обновлением требуется подтверждение",
        ["S_63ebd1103e"] = "Нельзя определить, какие каналы есть у этого интерфейса.",
        ["S_63ec387d75"] = "В сети {0} из {1} · обновлено {2:HH:mm:ss}",
        ["S_642459f784"] = "Не удаётся классифицировать устройство по VID/PID.",
        ["S_648435f237"] = "Ресивер не зарегистрирован: идентификация взята от самого устройства или от способа подключения, модель ресивера не подставляется.",
        ["S_651b087145"] = "Монитор отображения",
        ["S_6537db5fc7"] = "Недоступны и GitHub, и Gitee (GitHub: {0}; Gitee: {1})",
        ["S_65bd0c20f1"] = "Сбор остановлен, отчёт и диагностический пакет созданы.",
        ["S_65fc81e161"] = "Открыть",
        ["S_66675d281d"] = "Разрешить отправку устройству (ручная отправка кадров, эксперимент)",
        ["S_669814cbab"] = " · шаг {0}/{1}",
        ["S_66f36a0605"] = "<h1>VigilWatt Отчёт о сборе</h1>",
        ["S_671fbc43bf"] = "все данные считаны с этого компьютера в реальном времени, без домыслов. Отсутствие серийного номера означает, что устройство не предоставило строку, а не ошибку чтения.</p>",
        ["S_6721eb5f20"] = "Включён (report ID {0}, только чтение GET_REPORT)",
        ["S_674eaf783e"] = "<table><thead><tr><th>Время</th><th>Данные пользователя</th><th>Первый кадр после них</th>",
        ["S_6783cdc749"] = "{0:MM-dd HH:mm}, заряд {1}%",
        ["S_680671fa66"] = "Самая ранняя запись",
        ["S_68075dc4ab"] = "Часы",
        ["S_680e3e57e7"] = "Не удалось установить обновление",
        ["S_6815896741"] = "Не проверено",
        ["S_689cdd0f3c"] = "Два устройства одной модели могут быть объединены в одно, а разные MI одного донгла, наоборот, разделены — при выборе интерфейса ориентируйтесь на наличие входного канала.",
        ["S_68aff9a8b4"] = "Записано «{0}», дальше: {1}",
        ["S_69542e31d5"] = "Длина входного сообщения {0}, report ID {1}",
        ["S_69729065e4"] = "Макс. число устройств",
        ["S_69a63ddcff"] = "Устройство: {0}\nПериод: {1}\nЗаписей: {2}",
        ["S_69c48e1bff"] = " · все недоступны (защищены системой)",
        ["S_6a051bf65c"] = "Сохранено в {0}",
        ["S_6a3657d297"] = "), поэтому доступны только стандартные сообщения клавиатуры/мыши/потребительских устройств, а не фирменные протоколы заряда.",
        ["S_6b5fb4e34b"] = "HidP_GetCaps не выполнен",
        ["S_6b6fc740c0"] = "Путь устройства",
        ["S_6b7055e8d7"] = "Опрос Feature",
        ["S_6c14bd7f6f"] = "Закрыть",
        ["S_6c34f09098"] = "Данные производителя",
        ["S_6c72847d86"] = " записей, полные данные находятся в records.jsonl.</p>",
        ["S_6cad9198f2"] = "Не объявлено",
        ["S_6ccb1c30aa"] = "Заряд должен быть целым числом от 1 до 100.",
        ["S_6ccdedf273"] = "<p class=\"note\">Отметки действий пользователя — отдельные события, они не смешиваются с исходными сообщениями.</p></section>",
        ["S_6cfd6e9283"] = "Журналы очищены",
        ["S_6dacf0b9f8"] = " · интерфейсов: {0}",
        ["S_6dbe83233a"] = "; обычно канал настройки, может не содержать данных о состоянии",
        ["S_6dfe362bc6"] = "- В этот раз сообщений нет: возможно, устройство не отправляет данные спонтанно (нужно сначала открыть сеанс), выбран не тот интерфейс,",
        ["S_6e280a5484"] = "Без включённого чтения Feature собираются только входные отчёты, которые устройство отправляет само.",
        ["S_6f150d320a"] = "CreateFile вернул {0} (системно-защищённая collection)",
        ["S_6f1972e48e"] = "Выполняется",
        ["S_6f34fa28fc"] = "Действие нельзя отменить. Чтобы сохранить доказательства, выберите «Остановить и создать отчёт».",
        ["S_6f39593eff"] = "Оценка системы",
        ["S_6f9ddf1841"] = "<p class=\"muted\">В этот раз устройство не выбрано (собраны только данные уровня сеанса).</p></section>",
        ["S_70a2b88e7c"] = "История",
        ["S_7125dc174d"] = "Сводка скопирована, её можно вставить в issue или сообщение.",
        ["S_71281e518c"] = "<li>Время записывается и как монотонные часы (миллисекунды от начала сеанса), и как системное время (UTC); для сортировки используется первое.</li>",
        ["S_71683c08ba"] = "Время работы оценивается по недавнему изменению заряда; при нехватке данных или постоянном уровне показывается причина.",
        ["S_71712c0dc0"] = "Своя метка (необязательно), например: переключился на Bluetooth",
        ["S_72077749f7"] = "Нет",
        ["S_72250c5922"] = "Не удалось удалить",
        ["S_72a9c734b4"] = "Требует дополнительных средств",
        ["S_72afaa7508"] = "VID / PID / версия",
        ["S_72b1f9f267"] = "Плавающая полоска заряда на рабочем столе: перетаскивается, не появляется в Alt-Tab и на панели задач",
        ["S_7319539620"] = "Показать все возможности (включая доступные)",
        ["S_7328deebb5"] = "Подключение",
        ["S_738027119e"] = "<p class=\"note\">Этот сбор не записывает в устройство никаких сообщений и не перебирает report ID.",
        ["S_73cb7c10c9"] = "Требуется установить USBPcap (драйвер-фильтр); это приложение не устанавливает его за вас.",
        ["S_73e83b8f20"] = " Администратор={0} ",
        ["S_74d7a70b04"] = "Не удалось сохранить параметры, запись невозможна:\n{0}\\settings.json\n\n",
        ["S_74df625ee0"] = "Удалить устройство…",
        ["S_7502174118"] = "Этот интерфейс использует стандартную страницу HID ({0}): доступны только стандартные входные отчёты, фирменного протокола заряда здесь нет.",
        ["S_75589922ea"] = "Режим отображения",
        ["S_75ef1241c0"] = "Назад",
        ["S_7656b7e221"] = "Адаптировано ({0})",
        ["S_7741f9cc14"] = " · шаг завершён",
        ["S_774b680950"] = "Ресивер",
        ["S_775a85c9ab"] = "Длина {0}→{1}",
